/**
 * Web stub for CSS imports.
 *
 * The web bundle loads its Tailwind/NativeWind CSS as a plain stylesheet (`styles.css`, generated by
 * the Tailwind CLI in `pnpm web:bundle` and linked from `index.html`). Metro therefore must not try
 * to transform `global.css` itself — NativeWind's Metro integration serves it as a virtual file that
 * cannot be SHA-1'd during a one-shot web bundle. Every `.css` import resolves here instead, to an
 * empty module.
 */
module.exports = {};
